from pathlib import Path
from playwright.sync_api import sync_playwright,expect
p=argparse.ArgumentParser();p.add_argument('--base',required=True);p.add_argument('--access-json',required=True);p.add_argument('--qa-json',required=True);p.add_argument('--out',required=True);a=p.parse_args();base=a.base.rstrip('/');out=Path(a.out);out.mkdir(parents=True,exist_ok=True)
qa=json.loads(Path(a.qa_json).read_text());owner=json.loads(Path(a.access_json).read_text());checks=[];errors=[];tag='QA UX '+str(int(time.time()))
