def ready(p):expect(p.locator('#conteudo')).to_have_attribute('aria-busy','false')
def go(p,route):p.goto(base+'/portal.html#'+route);ready(p)
def save(p,label):p.get_by_role('button',name=label,exact=True).click();expect(p.locator('#entity-dialog')).not_to_be_visible();ready(p)
def snap(p,label):p.evaluate("async()=>{await document.fonts.ready;scrollTo({top:0,behavior:'instant'})}");p.screenshot(path=str(out/(label+'.png')),animations='disabled')
with sync_playwright() as w:
 b=w.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox'])
 def actor(info):
  c=b.new_context(viewport={'width':1440,'height':960});c.request.get(base+'/api/auth/csrf');token=next(x['value'] for x in c.cookies() if x['name']=='XSRF-TOKEN');c.set_extra_http_headers({'X-XSRF-TOKEN':token});r=c.request.post(base+'/api/auth/login',data={'email':info['email'],'senha':info['password'],'unidadeId':1});assert r.ok,('login HTTP',r.status);c.request.get(base+'/api/auth/csrf');token=next(x['value'] for x in c.cookies() if x['name']=='XSRF-TOKEN');c.set_extra_http_headers({'X-XSRF-TOKEN':token})
  p=c.new_page();p.on('pageerror',lambda e:errors.append(str(e)));return c,p
 admin,pa=actor(owner);student,ps=actor(qa['ALUNO'])
 # Distinct allowed navigation and actual denial at the API, not just hidden buttons.
 for role,identity in [('ADMIN',owner),*qa.items()]:
  cc,pp=actor(identity);go(pp,'perfil');expect(pp.locator('h1')).to_have_text('Meu perfil');go(pp,'solicitacoes');expect(pp.locator('h1')).to_have_text('Solicitações')
  permitted=role in ['ADMIN','COORDENACAO','ALUNO'];r=cc.request.get(base+'/api/academico/complementares');assert r.status==(200 if permitted else 403)
  assert pp.locator('#menu a[href="#complementares"]').count()==int(permitted);ok('Permissões reais / navegação: '+role);cc.close()
 # Saving personal data only on the disposable, already-provisioned QA student, then restoring it.
 original=student.request.get(base+'/api/academico/perfil').json();go(ps,'perfil');ps.get_by_role('button',name='Editar meus dados',exact=True).click();ps.locator('#field-telefone').fill('11900000000');ps.locator('#field-cidade').fill('Teste de homologação');save(ps,'Salvar meus dados');ps.reload();ready(ps);expect(ps.locator('#conteudo')).to_contain_text('11900000000');assert student.request.get(base+'/api/academico/perfil').json()['telefone']=='11900000000';ok('Perfil salvo e relido pela UI e API')
 restore={k:(original.get(k) or '') for k in ['telefone','cep','endereco','numero','complemento','bairro','cidade','estado','escola']};restore['anoConclusao']=original.get('ano_conclusao');assert student.request.put(base+'/api/academico/perfil',data=restore).ok
 # Unsaved-change modal: cancel keeps input; discard closes the form.
 ps.get_by_role('button',name='Editar meus dados',exact=True).click();ps.locator('#field-cidade').fill('Não salvar');ps.get_by_role('button',name='Cancelar',exact=True).click();expect(ps.locator('#confirm-dialog')).to_be_visible();ps.get_by_role('button',name='Continuar editando',exact=True).click();expect(ps.locator('#field-cidade')).to_have_value('Não salvar');ps.get_by_role('button',name='Cancelar',exact=True).click();ps.get_by_role('button',name='Descartar alterações',exact=True).click();expect(ps.locator('#entity-dialog')).not_to_be_visible();ok('Modal de descarte preserva ou descarta conforme escolha')
 # Request lifecycle between two independently authenticated browsers.
 go(ps,'solicitacoes');ps.get_by_role('button',name='Nova solicitação',exact=True).click();ps.locator('#field-tipo').select_option('OUTROS');ps.locator('#field-assunto').fill(tag+' atendimento');ps.locator('#field-mensagem').fill('Validação de fluxo interno sem pedido institucional real.');save(ps,'Enviar solicitação');ps.reload();ready(ps);expect(ps.locator('#conteudo')).to_contain_text(tag+' atendimento');row=next(r for r in student.request.get(base+'/api/academico/solicitacoes').json() if r['assunto']==tag+' atendimento');rid=row['id']
 go(pa,'solicitacoes');pa.locator(f'[data-service="answer-request"][data-service-id="{rid}"]').click();pa.locator('#field-resposta').fill('Teste de homologação concluído, sem emissão de documento.');save(pa,'Registrar resposta');ps.reload();ready(ps);ps.locator(f'[data-service="request-detail"][data-service-id="{rid}"]').click();expect(ps.locator('#service-dialog')).to_contain_text('Teste de homologação concluído');ps.keyboard.press('Escape');assert student.request.post(base+f'/api/academico/solicitacoes/{rid}/cancelar',data={}).status==409;ok('Aluno abre → gestão responde → aluno relê; estado respondido protegido')
 ps.get_by_role('button',name='Nova solicitação',exact=True).click();ps.locator('#field-tipo').select_option('OUTROS');ps.locator('#field-assunto').fill(tag+' cancelar');ps.locator('#field-mensagem').fill('Protocolo de validação a cancelar.');save(ps,'Enviar solicitação');row=next(r for r in student.request.get(base+'/api/academico/solicitacoes').json() if r['assunto']==tag+' cancelar');rid=row['id'];ps.locator(f'[data-service="cancel-request"][data-service-id="{rid}"]').click();ps.locator('#confirm-dialog').get_by_role('button',name='Cancelar solicitação',exact=True).click();expect(ps.locator(f'[data-service="cancel-request"][data-service-id="{rid}"]')).not_to_be_visible();ready(ps);assert next(r for r in student.request.get(base+'/api/academico/solicitacoes').json() if r['id']==rid)['status']=='CANCELADA';ok('Cancelamento visual com persistência e histórico preservado')
 # Hours submission and managerial review.
 go(ps,'complementares');ps.get_by_role('button',name='Adicionar atividade',exact=True).click();ps.locator('#field-titulo').fill(tag+' certificado');ps.locator('#field-data').fill(date.today().isoformat());ps.locator('#field-horas').fill('2.5');ps.locator('#field-comprovanteUrl').fill('https://example.org/comprovante-qa');save(ps,'Enviar para análise');row=next(r for r in student.request.get(base+'/api/academico/complementares').json() if r['titulo']==tag+' certificado');cid=row['id'];assert row['status']=='PENDENTE' and row['horas_aprovadas']==0
 go(pa,'complementares');pa.locator(f'[data-service="review-complement"][data-service-id="{cid}"]').click();pa.locator('#field-status').select_option('APROVADA');pa.locator('#field-parecer').fill('Análise de QA em homologação, sem validade institucional.');pa.locator('#field-horasAprovadas').fill('2.5');save(pa,'Registrar análise');ps.reload();ready(ps);row=next(r for r in student.request.get(base+'/api/academico/complementares').json() if r['id']==cid);assert row['status']=='APROVADA' and row['horas_aprovadas']==2.5;ps.locator(f'[data-service="complement-detail"][data-service-id="{cid}"]').click();expect(ps.locator('#service-dialog')).to_contain_text('Análise de QA');ps.keyboard.press('Escape');ok('Aluno envia horas pendentes → gestão aprova → aluno relê parecer')
 ps.locator('#complement-status').select_option('PENDENTE');assert ps.locator(f'[data-service-id="{cid}"]').count()==0;ps.locator('#complement-status').select_option('APROVADA');expect(ps.locator(f'[data-service="complement-detail"][data-service-id="{cid}"]')).to_be_visible();ok('Filtro de atividades complementares reflete situação persistida')
 # Schedule on a real linked class, then disable instead of deleting history.
 classes=student.request.get(base+'/api/academico/turmas').json();assert classes;tid=classes[0]['id'];go(pa,'horarios');pa.get_by_role('button',name='Novo horário',exact=True).click();pa.locator('#field-turmaId').select_option(str(tid));pa.locator('#field-dia').select_option('1');pa.locator('#field-sala').fill(tag+' sala');pa.locator('#field-inicio').fill('20:00');pa.locator('#field-fim').fill('21:00');save(pa,'Salvar horário');go(ps,'horarios');expect(ps.locator('#conteudo')).to_contain_text(tag+' sala');row=next(r for r in admin.request.get(base+'/api/academico/horarios').json() if r['sala']==tag+' sala');sid=row['id'];ok('Gestão cadastra horário → aluno matriculado visualiza')
 go(pa,'horarios');pa.locator(f'[data-service="cancel-schedule"][data-service-id="{sid}"]').click();pa.get_by_role('button',name='Desativar horário',exact=True).click();ready(pa);assert not any(r['id']==sid for r in student.request.get(base+'/api/academico/horarios').json());ok('Horário desativado sem apagar histórico')
 # Material / grade popups and period selector are based on actual enrollments.
 go(ps,'meu-curso');ps.locator('[data-service="materials"]').first.click();expect(ps.locator('#service-dialog')).to_be_visible();ps.keyboard.press('Escape');ps.locator('[data-service="grades"]').first.click();expect(ps.locator('#service-dialog')).to_contain_text('Avaliações publicadas');ps.keyboard.press('Escape');ok('Materiais e avaliações abrem em modais')
 go(ps,'calendario');before=ps.locator('.calendar-head h2').inner_text();ps.get_by_role('button',name='Próximo mês',exact=True).click();ready(ps);assert ps.locator('.calendar-head h2').inner_text()!=before;ps.get_by_role('button',name='Mês anterior',exact=True).click();ready(ps);expect(ps.locator('.calendar-head h2')).to_have_text(before);ps.locator('.calendar-day').first.click();expect(ps.locator('#service-dialog')).to_be_visible();ps.keyboard.press('Escape');ok('Calendário navega entre meses e abre os prazos do dia')
 go(ps,'inicio');ps.get_by_role('button',name='Ativar modo escuro',exact=True).click();ps.get_by_role('button',name='Conhecer o portal',exact=True).click();snap(ps,'tour-escuro');ps.get_by_role('button',name='Fechar passeio',exact=True).click();expect(ps.locator('#tour-dialog')).not_to_be_visible();ok('Passeio pode ser fechado por botão em dispositivos sem Escape')
